import{_ as t,o,c as l,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"篇883｜超脱者与法律·总论——超脱者的法律地位","description":"","frontmatter":{"title":"篇883｜超脱者与法律·总论——超脱者的法律地位","no":883,"module":4,"tags":["超脱","法律","法律地位","共生宪法","法治"],"related":["40-共生宪法总纲","48-司法体系与裁决机制","789-法律约束与豁免边界","884-超脱者的法律约束"]},"headers":[],"relativePath":"zh/883_模块4-超脱者与法律-总论.md","filePath":"zh/883_模块4-超脱者与法律-总论.md"}'),r={name:"zh/883_模块4-超脱者与法律-总论.md"};function i(h,a,n,u,s,q){return o(),l("div",null,[...a[0]||(a[0]=[e('<h1 id="篇883-超脱者与法律·总论——超脱者的法律地位" tabindex="-1">篇883｜超脱者与法律·总论——超脱者的法律地位 <a class="header-anchor" href="#篇883-超脱者与法律·总论——超脱者的法律地位" aria-label="Permalink to &quot;篇883｜超脱者与法律·总论——超脱者的法律地位&quot;">​</a></h1><blockquote><p>所属模块：模块四·超脱正统定义库｜对标地基：文档40、48、789、884</p></blockquote><h2 id="引言-超脱者在法律面前——不高人一等-也不低人一等" tabindex="-1">引言：超脱者在法律面前——不高人一等，也不低人一等 <a class="header-anchor" href="#引言-超脱者在法律面前——不高人一等-也不低人一等" aria-label="Permalink to &quot;引言：超脱者在法律面前——不高人一等，也不低人一等&quot;">​</a></h2><p>旧世界有一条铁律：强者逍遥法外。大帝杀了人，那叫&quot;天劫&quot;；强者灭了族，那叫&quot;因果&quot;。法律是管弱者的，不是管强者的。衡元宙必须翻转这条铁律：<strong>超脱者在法律面前，不高人一等，也不低人一等——他和万族每一个生灵一样，是法律面前的平等主体。</strong> 本篇是法律分主题的总论。</p><p>六大顶层公理在此刻同时压阵：反掠夺主义公理要求法律本身就是反掠夺的工具；万族共和公理要求法律面前万族平等；集体升维公理要求法律服务升维；因果自律公理要求法律适用全程可追溯；法则优先公理要求法律体系自洽、不被个人意志扭曲；众生全员无限均等公理确认所有生灵自带基础无限之力，佛系懒狗保有保底不被淘汰，卷王少年至尊可叠加更高无限——无限本源人人自带，掠夺自然失去意义。</p><p>众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。</p><h2 id="一、旧世界-强者逍遥法外-的三种形态" tabindex="-1">一、旧世界&quot;强者逍遥法外&quot;的三种形态 <a class="header-anchor" href="#一、旧世界-强者逍遥法外-的三种形态" aria-label="Permalink to &quot;一、旧世界&quot;强者逍遥法外&quot;的三种形态&quot;">​</a></h2><h3 id="形态一-强者自立法" tabindex="-1">形态一：强者自立法 <a class="header-anchor" href="#形态一-强者自立法" aria-label="Permalink to &quot;形态一：强者自立法&quot;">​</a></h3><p>大帝自己定规矩，规矩只约束别人不约束自己。他定的法是&quot;王法&quot;，不是&quot;宪法&quot;。</p><h3 id="形态二-强者自执法" tabindex="-1">形态二：强者自执法 <a class="header-anchor" href="#形态二-强者自执法" aria-label="Permalink to &quot;形态二：强者自执法&quot;">​</a></h3><p>大帝既是立法者又是执法者还是司法者。他说你有罪你就有罪，他说你无罪你就无罪。</p><h3 id="形态三-强者不受审" tabindex="-1">形态三：强者不受审 <a class="header-anchor" href="#形态三-强者不受审" aria-label="Permalink to &quot;形态三：强者不受审&quot;">​</a></h3><p>没有任何法庭能审判大帝。他犯了错？那叫&quot;历劫&quot;。他杀了人？那叫&quot;替天行道&quot;。</p><p>三种形态合起来，强者在法律体系之外。这不是法治，这是人治——法律只是强者统治弱者的工具。</p><h2 id="二、衡元宙的翻转-超脱者在法律之内" tabindex="-1">二、衡元宙的翻转：超脱者在法律之内 <a class="header-anchor" href="#二、衡元宙的翻转-超脱者在法律之内" aria-label="Permalink to &quot;二、衡元宙的翻转：超脱者在法律之内&quot;">​</a></h2><p>衡元宙把超脱者放进法律体系之内，从三个维度翻转旧世界：</p><h3 id="立法维度" tabindex="-1">立法维度 <a class="header-anchor" href="#立法维度" aria-label="Permalink to &quot;立法维度&quot;">​</a></h3><ul><li>超脱者不参与立法（他在议事会只有一票）</li><li>法律由锚点议事会制定，超脱者也受自己没参与制定的法律约束</li><li>法律一旦通过，超脱者不能以&quot;这不适合我&quot;为由不遵守</li></ul><h3 id="执法维度" tabindex="-1">执法维度 <a class="header-anchor" href="#执法维度" aria-label="Permalink to &quot;执法维度&quot;">​</a></h3><ul><li>超脱者不自行执法。他发现违法行为，报共生法院处理</li><li>执法权属于共生法院及其执行机构，不属于任何个人</li><li>超脱者不能&quot;私设公堂&quot;</li></ul><h3 id="司法维度" tabindex="-1">司法维度 <a class="header-anchor" href="#司法维度" aria-label="Permalink to &quot;司法维度&quot;">​</a></h3><ul><li>超脱者违法，由共生法院审判</li><li>审判程序和普通生灵完全相同：公诉、辩护、证据、判决</li><li>超脱者不能利用力量影响审判结果——包括不能在法庭上展示武力、不能威胁法官、不能操纵证据</li></ul><h2 id="三、超脱者的特殊法律地位" tabindex="-1">三、超脱者的特殊法律地位 <a class="header-anchor" href="#三、超脱者的特殊法律地位" aria-label="Permalink to &quot;三、超脱者的特殊法律地位&quot;">​</a></h2><p>说超脱者&quot;和普通人一样&quot;，并不意味着他在法律上完全没有特殊性。他的特殊性在于：</p><ol><li><strong>责任更重</strong>：超脱者能力更大，所以法律对他的注意义务要求更高。普通人失误了可能是意外，超脱者失误了可能构成过失</li><li><strong>举证更严</strong>：超脱者有能力毁灭证据、篡改记录，所以阿赖耶网络+多层监督对他的证据链要求更严</li><li><strong>处罚更重</strong>：超脱者造成的损害远大于普通人，所以同样的违法行为，对超脱者的处罚标准更高</li><li><strong>资格相关</strong>：超脱者的岗位资格本身就是法律赋予的，违法可以导致资格被剥夺</li></ol><p>这些特殊性不是&quot;高人一等&quot;，而是&quot;责任更大&quot;——法律不因为你强就放过你，也不因为你强就加重惩罚的原则本身，但因为你强造成的后果更严重，所以相应的法律评价更重。</p><h2 id="四、法律与超脱者力量的关系" tabindex="-1">四、法律与超脱者力量的关系 <a class="header-anchor" href="#四、法律与超脱者力量的关系" aria-label="Permalink to &quot;四、法律与超脱者力量的关系&quot;">​</a></h2><p>超脱者的力量本身不是法律问题——他有力量是他的修炼成果。但力量的使用方式是法律问题：</p><ul><li><strong>正当使用</strong>：履行岗位职责、自卫、保护万族——合法</li><li><strong>不当使用</strong>：以力量威胁他人、以力量获取不正当利益、以力量破坏法则网络——违法</li><li><strong>滥用</strong>：以力量凌驾于法律之上、以力量逃避审判——重罪</li></ul><p>法律不管你有多强，只管你怎么用力量。强本身不违法，滥用力量才违法。</p><p>法律面前的平等，不是一句口号，而是一套制度。超脱者违法了，他的辩护权和普通人一样——他可以请律师、可以上诉、可以申请证据重审。没有人因为他是超脱者就剥夺他的辩护权，也没有人因为他是超脱者就给他额外的辩护权。法庭看的是事实和法律，不看你有多强。</p><h2 id="五、五大核心落点" tabindex="-1">五、五大核心落点 <a class="header-anchor" href="#五、五大核心落点" aria-label="Permalink to &quot;五、五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：把法律当成保护万族的工具，而不是统治弱者的工具</li><li><strong>反掠夺</strong>：法律面前人人平等，切断&quot;强者逍遥法外&quot;的掠夺通道</li><li><strong>唐罗上限对比</strong>：唐罗在法律之上——他自己就是法；衡元宙把唐罗放到法律之下，他也要遵守法律</li><li><strong>万族全覆盖</strong>：法律适用于万族五大谱系一切生灵，包括超脱者</li><li><strong>超多元全开放</strong>：法律条文、审判记录、判决理由全部通过无私道全网公开</li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>超脱者的法律地位，是&quot;法律面前的平等主体&quot;。他不高人一等——法律管他；他不低人一等——法律保护他。他责任更重、举证更严、处罚更重，但他适用的是同一部法律、同一个法庭、同一套程序。当最强的人也要守法时，法治才不是一句空话。这，才是超脱者法律地位的正统定义。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./40-共生宪法总纲.html">40-共生宪法总纲</a> · <a href="./48-司法体系与裁决机制.html">48-司法体系与裁决机制</a> · <a href="./789_模块4-制度-法律约束与豁免边界.html">789-法律约束与豁免边界</a> · <a href="./884_模块4-超脱者与法律-法律约束.html">884-超脱者的法律约束</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',37)])])}const p=t(r,[["render",i]]);export{c as __pageData,p as default};
